css:
/* Post hero: the banner at the top of a blog post. The banner photo is the "Banner image" field on the placement (choose it from the Media Bin); with none chosen the band stays on ink. Category, date, read time and author are fields too. */
:root{--ph-black:#0B0B0B;--ph-g300:#D7D5CE}
.bz-section[data-bz-node="ph"]{position:relative;isolation:isolate;overflow:hidden;padding:118px 0 56px;background:var(--ph-black);color:#fff}
.bz-section[data-bz-node="ph"]::before{content:"";position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(180deg,rgba(11,11,11,.55),rgba(11,11,11,.9))}
[data-bz-node="ph"]>.bz-container{max-width:none;padding-inline:0}
[data-bz-node="ph"] .bz-block{padding-block:0}
[data-bz-node^="ph-banner"]{position:absolute;inset:0;z-index:0;padding:0;margin:0}
[data-bz-node^="ph-banner"] .bz-container,[data-bz-node^="ph-banner"] .bz-figure,[data-bz-node^="ph-banner"] img{width:100%;max-width:none;height:100%;margin:0;padding:0;border-radius:0;object-fit:cover}
[data-bz-node^="ph-banner"] .bz-photo--empty,[data-bz-node^="ph-banner"] .bz-placeholder{display:none}
[data-bz-node="ph-row"]{position:relative;z-index:2;width:100%;max-width:1280px;margin-inline:auto;padding-inline:24px;box-sizing:border-box;display:block}
[data-bz-node="ph-row"]>.bz-col{max-width:760px;padding:0}
[data-bz-node="ph-crumbs"]{margin-bottom:20px}
[data-bz-node="ph-crumbs"] p{margin:0;font:600 12px/1.4 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:#fff}
[data-bz-node="ph-crumbs"] a{color:#fff;text-decoration:none}
[data-bz-node="ph-crumbs"] a:hover{color:var(--ph-g300)}
[data-bz-node="ph-h"]{margin-bottom:24px}
[data-bz-node="ph-h"] h1{margin:0;color:#fff;font-size:clamp(28px,4.2vw,48px);line-height:1.1;letter-spacing:.01em;text-transform:uppercase}
[data-bz-node="ph-meta-col"]{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px 0;padding:0}
[data-bz-node="ph-meta-col"] .bz-block+.bz-block::before{content:"\00b7";margin:0 16px;color:var(--ph-g300)}
[data-bz-node="ph-meta-col"] .bz-block{display:flex;align-items:baseline}
[data-bz-node="ph-meta-col"] p{margin:0;font:600 12px/1.7 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--ph-g300)}
[data-bz-node="ph-category"] p{font-weight:800;color:#fff}
@media (max-width:900px){.bz-section[data-bz-node="ph"]{padding:108px 0 44px}[data-bz-node="ph-row"]{padding-inline:20px}}
